/**
 * 离线词典：网站自带一份从本机牛津导出的词库（public/dict/），本机没开 API、
 * 或者在线源够不着（dictionaryapi.dev 国内网络连不上）时，浏览器直接在同源下取
 * —— 不经过任何外部服务，线上点「词典」也有真内容。
 *
 * 词库由 tools/build-offline-dictionary.ts 从《牛津高阶英汉双解词典（第10版）》
 * 导出（用户知悉并同意随站点发布）：一条只有音标、词性、CEFR、中英释义和一条
 * 例句。变形词不在库里（导出时跳过了没有义项的壳子条目），照样走 lemmaCandidates
 * 拿原形再查一遍（reported → report），和本机 API 的行为一致。
 *
 * 文件布局是两层：<字母>.idx.json 是各分块的首词（有序，拿来二分），
 * <字母>-000.json… 是 ≤45KB 的词条块。实测线上从国内拉 iviany.github.io 单流只有
 * 2.6~54KB/s，一整片一两兆根本下不完；查一个词只拉「索引 + 一个块」两个小文件，
 * 慢网也扛得住，SW 缓存后同样不再重复下载。
 */
import { lemmaCandidates } from "@leafia/shared";
import type { LanguageInsight } from "@leafia/shared";

/** 生成端（tools/build-offline-dictionary.ts 的 CompactEntry）的形状，两边要一起改。 */
interface OfflineEntry {
  /** 头词 */
  w: string;
  /** 英音 / 美音 */
  uk?: string;
  us?: string;
  /** 词性 */
  pos?: string;
  /** CEFR 等级 */
  cefr?: string;
  /** 中文义（最多四条） */
  zh: string[];
  /** 第一条英文释义 */
  en?: string;
  /** 一条例句：[英文, 中文?] */
  ex?: [string, string?];
  infl?: string;
}

/** 一次请求等这么久：索引和分块都是小文件，慢网也拉得动；卡上不能一直转圈。 */
const TIMEOUT_MS = 10000;

/** 每个字母的小索引，取回来就记住（记忆里是 Promise，并发查询不会重复请求）。 */
const indexCache = new Map<string, Promise<string[] | null>>();
/** 每个数据块，取回来就记住；取失败会退掉，下次能重试。 */
const chunkCache = new Map<string, Promise<Map<string, OfflineEntry>>>();

function shardOf(word: string): string {
  const first = word.trim().toLowerCase().charAt(0);
  return first >= "a" && first <= "z" ? first : "_";
}

function fetchJson<T>(url: string): Promise<T> {
  const controller = new AbortController();
  const timer = window.setTimeout(() => controller.abort(), TIMEOUT_MS);
  return fetch(url, {
    signal: controller.signal,
    headers: { accept: "application/json" },
  })
    .then((response) => {
      if (!response.ok) throw new Error(String(response.status));
      return response.json() as Promise<T>;
    })
    .finally(() => window.clearTimeout(timer));
}

function loadIndex(letter: string): Promise<string[] | null> {
  const cached = indexCache.get(letter);
  if (cached) return cached;
  const promise = fetchJson<string[]>(
    `${import.meta.env.BASE_URL}dict/${letter}.idx.json`,
  ).catch(() => {
    indexCache.delete(letter);
    return null;
  });
  indexCache.set(letter, promise);
  return promise;
}

function loadChunk(
  letter: string,
  chunkIndex: number,
): Promise<Map<string, OfflineEntry>> {
  const key = `${letter}-${chunkIndex}`;
  const cached = chunkCache.get(key);
  if (cached) return cached;
  const file = `${letter}-${String(chunkIndex).padStart(3, "0")}`;
  const promise = fetchJson<OfflineEntry[]>(
    `${import.meta.env.BASE_URL}dict/${file}.json`,
  )
    .then(
      (list) =>
        new Map(list.map((entry) => [entry.w.trim().toLowerCase(), entry])),
    )
    .catch(() => {
      chunkCache.delete(key);
      return new Map<string, OfflineEntry>();
    });
  chunkCache.set(key, promise);
  return promise;
}

/** 在索引里二分：最后一个首词 ≤ 目标词的分块就是它；比第一块首词还小就没戏。 */
function chunkOf(index: string[], word: string): number {
  let low = 0;
  let high = index.length - 1;
  let found = -1;
  while (low <= high) {
    const mid = (low + high) >> 1;
    if (index[mid]! <= word) {
      found = mid;
      low = mid + 1;
    } else {
      high = mid - 1;
    }
  }
  return found;
}

async function lookupOnce(candidate: string): Promise<OfflineEntry | null> {
  const letter = shardOf(candidate);
  const index = await loadIndex(letter);
  if (!index || index.length === 0) return null;
  const chunkIndex = chunkOf(index, candidate);
  if (chunkIndex < 0) return null;
  const chunk = await loadChunk(letter, chunkIndex);
  return chunk.get(candidate) ?? null;
}

export async function lookupOfflineDictionary(
  word: string,
): Promise<LanguageInsight | null> {
  const term = word.trim();
  if (!term) return null;

  // 先查点的那个词，再挨个试原形（reported → report）；最多三个，别让人看着转圈。
  const attempts = [term, ...lemmaCandidates(term)]
    .map((candidate) => candidate.trim().toLowerCase())
    .filter(
      (candidate, index, list) => candidate && list.indexOf(candidate) === index,
    )
    .slice(0, 3);

  for (const candidate of attempts) {
    const entry = await lookupOnce(candidate);
    if (entry) return toInsight(entry, term);
  }
  return null;
}

function toInsight(entry: OfflineEntry, term: string): LanguageInsight {
  const pronunciation = [
    entry.uk ? `英 ${entry.uk}` : "",
    entry.us ? `美 ${entry.us}` : "",
  ]
    .filter(Boolean)
    .join("  ");

  return {
    term,
    // 查的是变形词时（reported → report），卡片照旧标一句「原形 report」。
    lemma: entry.w,
    meaningsZh: entry.zh.length > 0 ? entry.zh : [entry.en ?? entry.w],
    definitionEn: entry.en ?? entry.w,
    pronunciation: pronunciation || undefined,
    partOfSpeech: entry.pos,
    cefr: entry.cefr,
    collocations: [],
    examples: entry.ex
      ? [
          entry.ex[1]
            ? { text: entry.ex[0], translationZh: entry.ex[1] }
            : { text: entry.ex[0] },
        ]
      : [],
    usageNotes: [],
    provider: "dictionary",
    sourceLabel: "离线牛津",
  };
}
